import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  // Main container
  const group = new Group();

  // Create local timelines to clean up
  const timelines = [];

  // --- 1. STAGE BACKDROP (z = -2.5) ---
  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial();

  // High-fidelity gradient with spec colors
  const colorInk = vec3(0.086, 0.086, 0.114);      // #16161d
  const colorSurface = vec3(0.043, 0.043, 0.063);  // #0b0b10
  const colorAccent = vec3(1.0, 0.165, 0.22);       // #ff2a38

  // V-Gradient blended with a tiny touch of the accent at the top edge
  const vUv = uv();
  const baseGrad = mix(colorSurface, colorInk, vUv.y);
  const finalGrad = mix(baseGrad, colorAccent, vUv.y.pow(4.0).mul(0.12));

  backdropMat.colorNode = finalGrad;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  group.add(backdropMesh);

  // --- 2. LOCAL LIGHTING ENHANCEMENT ---
  // Ambient fill
  const localFill = new AmbientLight('#e8ecf2', 0.2);
  group.add(localFill);

  // Rim/Accent light to brush the machined edges
  const rimLight = new DirectionalLight('#ff2a38', 1.2);
  rimLight.position.set(-3, 3, -1);
  group.add(rimLight);

  // --- 3. MACHINED METAL FRAME & CARD (z = 0) ---
  // Aspect ratio based on source rect 512, 320 -> 1.6
  const width = 3.2;
  const height = 2.0;

  // Outer metal bevel backing
  const frameGeo = new PlaneGeometry(width + 0.08, height + 0.08);
  const frameMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -0.01);
  group.add(frameMesh);

  // Inner deep card face
  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshStandardNodeMaterial({
    color: '#0b0b10',
    metalness: 0.1,
    roughness: 0.6,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Load and apply the image texture if available
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    cardMat.map = texture;
    cardMat.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load card texture, falling back to clean look', err);
  });

  // --- 4. ENTRANCE ANIMATION ---
  // Subtle elegant weighted-settle rise-in
  cardMesh.position.y = -0.15;
  frameMesh.position.y = -0.15;
  cardMesh.scale.set(0.98, 0.98, 1);
  frameMesh.scale.set(0.98, 0.98, 1);

  const introTimeline = gsap.timeline();
  introTimeline.to([cardMesh.position, frameMesh.position], {
    y: 0,
    duration: 1.1,
    ease: 'power4.out',
  });
  introTimeline.to([cardMesh.scale, frameMesh.scale], {
    x: 1,
    y: 1,
    duration: 1.1,
    ease: 'back.out(1.04)',
  }, 0);

  timelines.push(introTimeline);

  // --- 5. CLEANUP HANDLER ---
  group.userData.cleanup = function () {
    // Kill GSAP animations
    timelines.forEach((tl) => tl.kill());

    // Dispose geometry
    backdropGeo.dispose();
    frameGeo.dispose();
    cardGeo.dispose();

    // Dispose materials
    backdropMat.dispose();
    frameMat.dispose();
    cardMat.dispose();
  };

  return group;
}
